"""Greedy: play the most valuable word the rack allows."""
import spindle


def choose(rack, words):
    best = None
    for w in sorted(words):
        if len(w) >= 3 and spindle.formable(w, rack):
            p = spindle.points(w)
            if best is None or p > best[0]:
                best = (p, w)
    return None if best is None else best[1]

