"""Spindle: a word game with a rack and a bag. The rules are in README.md."""

# ---- house rules for this table (they are part of the specification, see README.md) ----
COUNTS = {'a': 6, 'b': 2, 'e': 4, 'g': 2, 'i': 6, 'k': 4, 'm': 2, 'o': 4, 'r': 3, 's': 3, 't': 3, 'u': 6}
VALUES = {'a': 1, 'b': 4, 'e': 1, 'g': 2, 'i': 1, 'k': 1, 'm': 3, 'o': 1, 'r': 3, 's': 3, 't': 3, 'u': 1}
MULT = {3: 1, 4: 2, 5: 3, 6: 5, 7: 8}
SPINDLE_BONUS = 40
ECHO_BONUS = 6
RACK_SIZE = 7
MAX_TURNS = 10
# --------------------------------------------------------------------------------------


MIN_LENGTH = 3


def points(word):
    """Points of a word (it is not checked against any rack or dictionary)."""
    base = sum(VALUES[c] for c in word)
    total = base * MULT[len(word)]
    total += ECHO_BONUS * sum(1 for a, b in zip(word, word[1:]) if a == b)
    if len(word) == RACK_SIZE:
        total += SPINDLE_BONUS
    return total


def formable(word, rack):
    """True if the word can be spelled with the tiles of the rack (a string or list of letters)."""
    left = list(rack)
    for c in word:
        if c not in left:
            return False
        left.remove(c)
    return True


class Game:
    def __init__(self, seed, words):
        self.state = seed & 0x7FFFFFFF
        self.words = frozenset(words)
        self.bag = [ch for ch in sorted(COUNTS) for _ in range(COUNTS[ch])]
        self.rack = []
        self.score = 0
        self.turn = 1
        self._refill()

    def _next(self):
        self.state = (self.state * 1103515245 + 12345) & 0x7FFFFFFF
        return self.state

    def _refill(self):
        while len(self.rack) < RACK_SIZE and self.bag:
            self.rack.append(self.bag.pop((self._next() >> 8) % len(self.bag)))
        self.rack.sort()

    def is_over(self):
        return self.turn > MAX_TURNS or not self.rack

    def play(self, word):
        if self.is_over():
            raise ValueError("game over")
        if len(word) < MIN_LENGTH:
            raise ValueError("too short")
        if word not in self.words:
            raise ValueError("not in dictionary")
        if not formable(word, self.rack):
            raise ValueError("not on the rack")
        for c in word:
            self.rack.remove(c)
        gained = points(word)
        self.score += gained
        self.turn += 1
        self._refill()
        return gained

    def skip(self):
        if self.is_over():
            raise ValueError("game over")
        self.rack = []
        self.turn += 1
        self._refill()

    def render(self):
        head = "turn %d/%d score %d bag %d" % (min(self.turn, MAX_TURNS), MAX_TURNS, self.score, len(self.bag))
        if self.is_over():
            head += " GAME OVER"
        return head + "\nrack: " + " ".join(self.rack)

